import { expect, test } from '../fixtures';

/** A value that is new on every run (an email, a name), so a second run does not collide with the first. */
function makeUnique(): (base: string) => string {
  const seen = new Map<string, string>();
  return (base) => {
    const known = seen.get(base);
    if (known) return known;
    const tag = Math.random().toString(36).slice(2, 8);
    const at = base.indexOf('@');
    const value = at === -1 ? `${base}-${tag}` : `${base.slice(0, at)}+${tag}${base.slice(at)}`;
    seen.set(base, value);
    return value;
  };
}

test('Topic new', async ({ page }) => {
  const unique = makeUnique();

  await test.step('Open the new topic form in Welcome', async () => {
    await page.goto('/1-welcome/topic/new');
  });

  await test.step('Type a title', async () => {
    await page.getByRole('textbox', { name: 'Topic title', exact: true }).fill(unique('Planning notes'));
  });

  await test.step('Type the post content', async () => {
    await page.getByRole('textbox', { name: 'Content', exact: true }).fill('Notes about the release.');
  });

  await test.step('Press Post topic', async () => {
    await page.getByRole('button', { name: 'Post topic', exact: true }).click();
  });

  await test.step('The member lands on the new topic page [code]', async () => {
    await expect(page).toHaveURL(/\/topic\//);
  });

  await test.step('The posted content is shown [code]', async () => {
    await expect(page.getByRole('paragraph').filter({ hasText: /^Notes about the release\.$/ })).toBeVisible();
  });
});
